import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import test from 'node:test'

const fixtureSource = readFileSync('/home/liuxuedeng/Django-Agent/frontend/src/views/Wiki.page-actions.test.mjs', 'utf8')
const code = fixtureSource.match(/let input = ''; for await \(const chunk of req\) input \+= chunk\n    const body = input \? JSON\.parse\(input\) : undefined/)?.[0]
assert.ok(code, 'Read the actual existing fixture body decoder')
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
const readCurrentFixtureBody = new AsyncFunction('req', `${code}\nreturn body`)
const content = Array.from({ length: 80 }, (_, index) => `第${index + 1}行：完整保留 Markdown 内容。`).join('\n')
const bytes = Buffer.from(JSON.stringify({ title: '长正文验收', content }))
const split = bytes.indexOf(Buffer.from('第66行')) + Buffer.byteLength('第66') + 2
const chunks = [bytes.subarray(0, split), bytes.subarray(split)]

test('actual existing Wiki fixture decoder preserves UTF-8 when HTTP chunks split a Chinese character', async () => {
  const parsed = await readCurrentFixtureBody(chunks)
  console.log(JSON.stringify({ fixture: 'frontend/src/views/Wiki.page-actions.test.mjs:46', splitByte: split, bytes: bytes.length, actualLine66: parsed.content.split('\n')[65], expectedLine66: content.split('\n')[65] }))
  assert.equal(parsed.content, content)
})

test('decoding concatenated bytes once preserves the same fragmented JSON content', () => {
  assert.equal(JSON.parse(Buffer.concat(chunks).toString('utf8')).content, content)
})
